Subroutine ConsultarClima() As Result<String, IoError>
  Define red As NetworkCap <- Propagate requestNetwork();
  Define peticion As HttpRequest <- HttpRequest(HttpMethod.GET, "https://clima.test/hoy");
  Define respuesta As HttpResponse <- Propagate red.send(peticion);
  Write "Estado: ", respuesta.status();
  Return respuesta.textBody();
EndSubroutine

Algorithm Clima
  Switch ConsultarClima() Do
    Success(texto): Write texto;
    Failure(problema): Write problema.code;
  EndSwitch
EndAlgorithm
